                <label class="mt-4 block text-sm font-medium text-slate-700 dark:text-slate-200">Upload or replace watermark<input type="file" name="watermark" accept="image/png,image/jpeg,image/webp" class="mt-2 block w-full text-sm text-slate-500 file:mr-3 file:rounded-md file:border-0 file:bg-slate-100 file:px-3 file:py-2 file:font-semibold file:text-slate-700 dark:file:bg-slate-800 dark:file:text-slate-200"><span class="mt-1 block text-xs font-normal text-slate-500 dark:text-slate-400">PNG, JPG, or WEBP, up to 2 MB. The image is stored privately.</span>@error('watermark')<span class="mt-1 block text-xs font-normal text-rose-600 dark:text-rose-300">{{ $message }}</span>@enderror</label>
