    <script>
        (() => { const form=document.querySelector('[data-invoice-design-form]'), cards=[...document.querySelectorAll('[data-template-card]')], preview=document.querySelector('[data-invoice-design-preview]'), count=document.querySelector('[data-template-count]'), orientation=document.querySelector('[data-orientation-control]'), taxFilter=document.querySelector('[data-template-filter="tax"]'), gstFilter=document.querySelector('[data-template-filter="gst"]'), styleFilter=document.querySelector('[data-template-filter="style"]'), titleSelect=form.querySelector('[data-document-title-select]'), customTitle=form.querySelector('[data-custom-document-title]'), titlePreviews=[...document.querySelectorAll('[data-document-title-preview]')], watermarkInput=form.querySelector('input[name="watermark"]'), watermarkPreview=form.querySelector('[data-watermark-preview]'), watermarkEmpty=form.querySelector('[data-watermark-empty]'), replaceAccount=form.querySelector('[data-replace-account-number]'), accountInput=form.querySelector('[data-account-number-input]'); const formats={!! json_encode($templates) !!}, titleLabels={!! json_encode($documentTitleOptions) !!}; const selectedFormat=()=>form.querySelector('input[name="paper_format"]:checked')?.value; const selectedTemplate=()=>form.querySelector('input[name="template_key"]:checked')?.value; const refreshTitle=()=>{const custom=String(form.querySelector('input[name="custom_document_title"]')?.value||'').trim(), title=titleSelect?.value==='custom'?(custom||'CUSTOM TITLE'):(titleLabels[titleSelect?.value]||'INVOICE');customTitle?.classList.toggle('hidden',titleSelect?.value!=='custom');titlePreviews.forEach(element=>element.textContent=title)}; const refreshAccountInput=()=>{if(!replaceAccount||!accountInput)return;accountInput.disabled=!replaceAccount.checked;accountInput.classList.toggle('hidden',!replaceAccount.checked);if(!replaceAccount.checked)accountInput.value='';}; const refresh=()=>{const format=selectedFormat(), tax=taxFilter.value, gst=gstFilter.value, style=styleFilter.value; let visible=0; cards.forEach(card=>{const supportsTax=(card.dataset.taxModes||'').split(',').includes(tax);const show=card.dataset.paper===format&&(!tax||supportsTax)&&(!gst||card.dataset.gst===gst)&&(!style||card.dataset.style===style);card.classList.toggle('hidden',!show);if(show)visible++;const checked=card.querySelector('input').checked;card.querySelector('[data-selected-badge]').classList.toggle('hidden',!checked)});let key=selectedTemplate();const selectedCard=cards.find(card=>card.querySelector('input').value===key);if(!formats[key]||!selectedCard||selectedCard.classList.contains('hidden')){const first=cards.find(card=>!card.classList.contains('hidden'));if(first){first.querySelector('input').checked=true;key=first.querySelector('input').value;}}cards.forEach(card=>card.querySelector('[data-selected-badge]').classList.toggle('hidden',!card.querySelector('input').checked));const orientations=formats[key]?.orientations||[];orientation.classList.toggle('hidden',orientations.length===0);const select=orientation.querySelector('select');[...select.options].forEach(option=>option.hidden=!orientations.includes(option.value));if(!orientations.includes(select.value))select.value='portrait';count.textContent=`${visible} design${visible===1?'':'s'} available`;refreshTitle();if(preview){const data=new FormData(form);const query=new URLSearchParams();data.forEach((value,key)=>{if(key!=='_token'&&key!=='_method'&&typeof value==='string'&&!key.match(/^(account_|bank_|ifsc_|swift_|upi_|payment_url|payment_note)/))query.append(key,value)});preview.src=`${preview.dataset.previewUrl}?${query}`;}};form.addEventListener('change',refresh);replaceAccount?.addEventListener('change',refreshAccountInput);form.addEventListener('input',event=>{if(['brand_color','payment_qr_uri','custom_document_title'].includes(event.target.name))refresh()});watermarkInput?.addEventListener('change',()=>{const file=watermarkInput.files?.[0];if(!file)return;const reader=new FileReader();reader.addEventListener('load',()=>{watermarkPreview.src=String(reader.result);watermarkPreview.classList.remove('hidden');watermarkEmpty.classList.add('hidden')});reader.readAsDataURL(file)});refreshAccountInput();refresh();})();
    </script>
